def minimum_flips_after_rotations(s):
    length = len(s)
    doubled = s + s
    mismatch = 0
    answer = length
    for right, char in enumerate(doubled):
        mismatch += char != ("0" if right % 2 == 0 else "1")
        if right >= length:
            left = right - length
            mismatch -= doubled[left] != ("0" if left % 2 == 0 else "1")
        if right >= length - 1:
            answer = min(answer, mismatch, length - mismatch)
    return answer

